import {
  View,
  TouchableOpacity,
  TextInput,
  FlatList,
  Text,
  useWindowDimensions,
  Pressable,
  StyleSheet,
  LayoutChangeEvent,
  Alert,
  ActivityIndicator,
} from 'react-native'
