import { ProjectGroupRevisionAction } from '@/generated/graphql'
import { useCurrentOrganization } from '@/utils/hooks'
import { useSpeechPermissionStore } from '@/stores'
import { CancelButton } from './buttons/CancelButton'
import { SubmitButton } from './buttons/SubmitButton'
import { MicButton } from './buttons/MicButton'

const TEXT_INPUT_MAX_LINES_OPEN = 6
const TEXT_INPUT_MAX_LINES_CLOSED = 3
const TEXT_INPUT_LINE_HEIGHT = 24
const MAX_FILE_SIZE = 20 * 1024 * 1024 // 20MB in bytes

export type MenuActionWithCustomIcon = MenuAction & {
  action: ProjectGroupRevisionAction
  isThinkingMode: boolean
}

const getModeActions = ({
  theme,
  canUseMAX
}: {
  theme: Theme
  canUseMAX: boolean
}): MenuActionWithCustomIcon[] => [
    {
      id: 'fast',
      imageColor: colors[theme].gray[900],
      titleColor: colors.light.orange[500],
      title: 'Fast',
      action: ProjectGroupRevisionAction.CHAT,
      isThinkingMode: false
    },
    {
      id: 'discussion',
      imageColor: colors[theme].gray[900],
      title: 'Discussion',
      action: ProjectGroupRevisionAction.DISCUSSION,
      isThinkingMode: true
    },
    {
      id: 'thinking',
      imageColor: colors[theme].gray[900],
      title: 'Thinking',
      action: ProjectGroupRevisionAction.CHAT,
      isThinkingMode: true
    },
    ...(canUseMAX
      ? [
        {
          id: 'max',
          imageColor: colors[theme].gray[900],
          title: 'MAX',
          action: ProjectGroupRevisionAction.EXPERT_SWE,
          isThinkingMode: true
        }
      ]
      : []),
    {
      id: 'auto',
      imageColor: colors[theme].gray[900],
      title: 'Auto',
      action: ProjectGroupRevisionAction.AUTO_SELECT_CHAT,
      isThinkingMode: false
    }
  ]

type BottomProps = {
  shouldShowMessages: boolean
  suggestions: Suggestion[]
  handleStart: () => void
  handleSubmit: ({
    prompt,
    assetsArray,
    action,
    isThinkingMode
  }: {
    prompt: string
    assetsArray: string[]
    action: ProjectGroupRevisionAction
    isThinkingMode: boolean
  }) => Promise<void>
  handleCancel: () => Promise<void>
  chatAssets: string[]
  setChatAssets: (chatAssets: string[]) => void
  prompt: string
  setPrompt: (prompt: string) => void
  bottomContainerHeight: number
  setBottomContainerHeight: (height: number) => void
  isLauncher: boolean
  canUseMAX: boolean
  onFocusInput?: React.MutableRefObject<(() => void) | null>
  projectGroupId: string
}

export const Bottom = ({
  shouldShowMessages,
  suggestions,
  handleStart,
  handleSubmit,
  handleCancel,
  chatAssets,
  setChatAssets,
  prompt,
  setPrompt,
  bottomContainerHeight,
  setBottomContainerHeight,
  isLauncher,
  canUseMAX,
  onFocusInput,
  projectGroupId
}: BottomProps) => {
  const { currentOrganization } = useCurrentOrganization()
  const { theme } = useTheme()
  const insets = useSafeAreaInsets()
  const { height: screenHeight } = useWindowDimensions()
  const promptInputRef = useRef<TextInput>(null)
  const hasMeasuredRef = useRef<boolean>(false)
  const { hasSpeechPermission } = useSpeechPermissionStore()
  const [isKeyboardOpen, setIsKeyboardOpen] = useState<boolean>(false)

  useEffect(() => {
    if (onFocusInput) {
      onFocusInput.current = () => {
        promptInputRef.current?.focus()
      }
    }
  }, [onFocusInput])

  const modeActions = getModeActions({ theme, canUseMAX })
  const [mode, setMode] = useState<MenuActionWithCustomIcon>(
    modeActions.find((action) => action.id === 'auto')!
  )
  const [isExpanded, setIsExpanded] = useState<boolean>(false)
  const [isMoreThanThreeLines, setIsMoreThanThreeLines] =
    useState<boolean>(false)
  const [isLongPressing, setIsLongPressing] = useState<boolean>(false)

  const chatState = useChatStore((state) => state.value.chatState)
  const onBottomContainerLayout = (event: LayoutChangeEvent) => {
    if (hasMeasuredRef.current) return

    const { height } = event.nativeEvent.layout
    setBottomContainerHeight(height + (isLauncher ? 20 : 0))
    hasMeasuredRef.current = true
  }

  const handleAddImagesPress = async () => {
    const { granted } = await ImagePicker.requestMediaLibraryPermissionsAsync()
    if (!granted) {
      Alert.alert('Permission to access media library is required.')
      return
    }

    let result = await ImagePicker.launchImageLibraryAsync({
      mediaTypes: ['images'],
      allowsMultipleSelection: true,
      selectionLimit: 4,
      orderedSelection: true,
      quality: 1
    })

    if (!result.canceled) {
      const validAssets = result.assets.filter((asset) => {
        const fileSize = asset.fileSize || MAX_FILE_SIZE + 1
        return fileSize <= MAX_FILE_SIZE
      })

      if (validAssets.length !== result.assets.length) {
        const rejectedCount = result.assets.length - validAssets.length
        Alert.alert(
          'Some images were too large',
          `${rejectedCount} image${rejectedCount > 1 ? 's were' : ' was'
          } rejected because they exceed 20MB.`
        )
      }

      if (validAssets.length > 0) {
        setChatAssets([...chatAssets, ...validAssets.map((asset) => asset.uri)])
      }

      try {
        const uploadedAssets = await uploadMany(
          validAssets.map((asset) => asset.uri)
        )
        setChatAssets([...chatAssets, ...uploadedAssets])
      } catch (error) {
        console.error('Upload failed:', error)
        Alert.alert(
          'Upload Failed',
          'Failed to upload images. Please try again.'
        )
      }
    }
  }

  const handleSubmitPress = async () => {
    promptInputRef.current?.blur()
    await handleSubmit({
      prompt,
      assetsArray: chatAssets,
      action: mode.action,
      isThinkingMode: mode.isThinkingMode
    })
  }

  const handleMicPress = () => {
    promptInputRef.current?.blur()
    handleStart()
  }

  if (!currentOrganization || hasSpeechPermission === null) return null

  if (currentOrganization.hasReachedChatCreditsLimit) {
    return (
      <ProjectCreationBlockerContainer
        hasReachedChatCreditsLimit={true}
        hasSpeechPermission={hasSpeechPermission}
      />
    )
  }

  const renderActionButton = () => {
    switch (chatState) {
      case 'READY':
        if (!prompt.trim() && chatAssets.length === 0) {
          return <MicButton handleMicPress={handleMicPress} />
        }
        return <SubmitButton handleSubmitPress={handleSubmitPress} />
      case 'PENDING':
        return (
          <ActivityIndicator size="small" color={colors[theme].gray[900]} />
        )
      default: // PENDING or GENERATING: show cancel button
        return <CancelButton handleCancel={handleCancel} />
    }
  }

  return (
    <View
      onLayout={onBottomContainerLayout}
      style={[
        styles.bottomContainer,
        bottomContainerHeight > 0 &&
        !shouldShowMessages && {
          height: bottomContainerHeight,
          marginBottom: insets.bottom
        },
        shouldShowMessages && {
          position: 'absolute',
          bottom: insets.bottom,
          width: '100%'
        }
      ]}
    >
      <AnimatePresence>
        {(isKeyboardOpen || isExpanded || isLongPressing) && (
          <MotiView
            from={{ opacity: 0 }}
            animate={{ opacity: isLongPressing ? 0 : 1 }}
            exit={{ opacity: 0 }}
            style={[
              StyleSheet.absoluteFillObject,
              {
                zIndex: 4,
                position: 'absolute',
                top: -screenHeight, // extend entire screen height
                bottom: -insets.bottom // component is insets away from bottom so close it out
              }
            ]}
          >
            <BlurView
              style={StyleSheet.absoluteFillObject}
              intensity={35}
              tint="systemChromeMaterial"
              pointerEvents="none"
            />
            <Pressable
              onLongPress={() => {
                setIsLongPressing(true)
                promptInputRef.current?.blur()
              }}
              onPressOut={() => {
                if (!isLongPressing) return
                setIsLongPressing(false)
                promptInputRef.current?.focus()
              }}
              onPress={() => {
                promptInputRef.current?.blur()
              }}
              style={StyleSheet.absoluteFillObject}
            />
          </MotiView>
        )}
      </AnimatePresence>
      {!prompt.trim() && !isExpanded && !shouldShowMessages && (
        <FlatList
          data={suggestions}
          renderItem={({ item }) => (
            <TouchableOpacity
              key={item.id}
              style={styles.suggestionItem(theme)}
              onPress={() => {
                Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium)
                setPrompt(item.prompt)
                promptInputRef.current?.focus()
              }}
            >
              <Text style={styles.suggestionItemText(theme)}>{item.label}</Text>
            </TouchableOpacity>
          )}
          horizontal
          showsHorizontalScrollIndicator={false}
          contentContainerStyle={styles.suggestionsList}
        />
      )}
      <KeyboardStickyView
        offset={{ closed: 0, opened: 20 }}
        pointerEvents="box-none"
        style={{ zIndex: 5 }}
      >
        <View
          style={[
            (isKeyboardOpen || isExpanded) && styles.bottomInputContainerOpen
          ]}
        >
          {shouldShowMessages && (
            <TouchableOpacity
              activeOpacity={0.8}
              style={styles.previewTab(theme)}
              onPress={() => {
                Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium)
                router.push({
                  pathname: '/preview',
                  params: { projectGroupId }
                })
              }}
            >
              <ExternalLink
                size={14}
                color={colors[theme].gray[900]}
              />
              <Text style={styles.previewTabText(theme)}>View Preview</Text>
            </TouchableOpacity>
          )}
          <LiquidGlassView
            isInteractive={true}
            glassEffectStyle="regular"
            style={[
              styles.bottomInputContainer,
              {
                borderWidth: 1,
                borderTopWidth: 0,
                borderColor: colors[theme].gray[50],
                overflow: 'hidden'
              },
              shouldShowMessages && {
                borderTopLeftRadius: 0,
                borderTopRightRadius: 0
              }
            ]}
          >
            <AssetsContainer
              chatAssets={chatAssets}
              setChatAssets={setChatAssets}
            />
            <TextInput
              ref={promptInputRef}
              value={prompt}
              onChangeText={setPrompt}
              onContentSizeChange={(event) => {
                setIsMoreThanThreeLines(
                  event.nativeEvent.contentSize.height >=
                  TEXT_INPUT_LINE_HEIGHT * TEXT_INPUT_MAX_LINES_OPEN
                )
              }}
              multiline={true}
              numberOfLines={
                isExpanded
                  ? 10
                  : isKeyboardOpen
                    ? TEXT_INPUT_MAX_LINES_OPEN
                    : TEXT_INPUT_MAX_LINES_CLOSED
              }
              style={styles.bottomInput(theme)}
              onFocus={() => {
                Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium)
                setIsKeyboardOpen(true)
              }}
              placeholder="Describe your app idea..."
              placeholderTextColor={colors[theme].gray[600]}
              onBlur={() => {
                setIsKeyboardOpen(false)
                setIsExpanded(false)
              }}
            />
            <AnimatePresence>
              {isMoreThanThreeLines && (
                <MotiView
                  from={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  exit={{ opacity: 0 }}
                  style={styles.bottomInputExpandButtonContainer}
                >
                  <TouchableOpacity
                    style={styles.bottomInputExpandButton}
                    onPress={() => setIsExpanded(!isExpanded)}
                  >
                    {isExpanded ? (
                      <Minimize2 size={20} color={colors[theme].gray[800]} />
                    ) : (
                      <Maximize2 size={20} color={colors[theme].gray[800]} />
                    )}
                  </TouchableOpacity>
                </MotiView>
              )}
            </AnimatePresence>
            <View style={styles.bottomInputContainerActions}>
              <View style={styles.bottomInputContainerActionsLeft}>
                <TouchableOpacity
                  style={styles.bottomInputAddAction}
                  onPress={handleAddImagesPress}
                >
                  <ImagePlus size={24} color={colors[theme].gray[400]} />
                </TouchableOpacity>
                <ModeDropdown
                  mode={mode}
                  setMode={setMode}
                  actions={modeActions}
                />
              </View>
              <AnimatePresence exitBeforeEnter>
                {renderActionButton()}
              </AnimatePresence>
            </View>
          </LiquidGlassView>
        </View>
      </KeyboardStickyView>
    </View>
  )
}

